import{_ as t,a,o,a4 as s}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Checkout","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/checkout/index.md","filePath":"api/graphql-api/shop/checkout/index.md","lastUpdated":1783079210000}'),i={name:"api/graphql-api/shop/checkout/index.md"};function r(h,e,d,n,p,c){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h1><p>The Checkout menu turns a prepared cart into a placed order. It runs as an ordered sequence — set the address, pick a shipping method, pick a payment method, then place the order — and provides queries to read the saved addresses and the available shipping / payment options at each step.</p><h2 id="the-checkout-sequence" tabindex="-1">The checkout sequence <a class="header-anchor" href="#the-checkout-sequence" aria-label="Permalink to &quot;The checkout sequence&quot;">​</a></h2><p>Checkout must run in order, because each step depends on the one before:</p><ol><li><strong>Set the checkout address</strong> (billing, and shipping unless the cart is virtual / downloadable only).</li><li><strong>Get shipping methods</strong> for the saved address, then <strong>set the chosen shipping method</strong>.</li><li><strong>Get payment methods</strong> available once shipping is selected, then <strong>set the chosen payment method</strong>.</li><li><strong>Place the order</strong> to finalise the cart into an order.</li></ol><p>Calling a step out of sequence (for example, fetching shipping methods before an address is saved) fails — finish the previous step first.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-addresses.html">Get Addresses</a></td><td><code>addresses</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-shipping-methods.html">Get Shipping Methods</a></td><td><code>shippingMethods</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-payment-methods.html">Get Payment Methods</a></td><td><code>paymentMethods</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/set-billing-address.html">Set Checkout Address</a></td><td><code>saveCheckoutAddresses</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/set-shipping-method.html">Set Shipping Method</a></td><td><code>saveShippingMethod</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/set-payment-method.html">Set Payment Method</a></td><td><code>savePaymentMethod</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/place-order.html">Place Order</a></td><td><code>placeOrder</code> mutation</td></tr></tbody></table><p>Checkout operates on the cart (identified by its cart token); a guest needs only the storefront key, while a signed-in customer also sends their Bearer token. See <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',9)]))}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
